cat > impl-regen/main.go <<'EOF'
// derives: C1.1, C1.2, C1.3, C1.4, C2.1, C2.2, C3.1, C3.4, C3.5, C3.7, C3.8, F1.1, F1.2, F1.3, F2.1, F2.2, F3.1, F3.2, F3.3
package main

import (
 \"encoding/json\"
 \"fmt\"
 \"os\"
 \"sort\"
 \"reflect\"
 \"math/rand\"
)
type M = map[string]interface{}
type Step struct { At interface{} "'`json:"at"`; Do M `json:"do"` }
type Schedule struct { Schedule string; Derives []string; Processes map[string][]string; Steps []Step; End interface{}; Bound map[string]int; Lifetime int }
type Node struct { Inc,Seq,Epoch,Token,Term int; Members []string; Up,Paused,Admitted bool; Promise int; Accepted *Entry; Learned []Entry }
type Entry struct { Proposal M; Epoch,Token,Term int; Members []string; Client,Request,Receiver,Operator string; Ref M }
type Task struct { To string; F func() }
type Pending struct { Receiver,Operator,ID string; Members []string; Ref M; Epoch int }
type Sim struct { S Schedule; Nodes map[string]*Node; Down map[string]bool; Queue []Task; Trace []M; Step,Arm,EndArm int; Ready bool; Resolved M; Grantor,Holder,CrashedFollower string; Grants map[string][]M; Waiting map[string]M; Pending []*Pending; Token,Term,Epoch,Ledger,Tick int; Members []string; Value interface{}; Mut,Clause,Failure string; Rng *rand.Rand; Busy bool; Out *os.File; Run string; Clocks map[string]int }
// derives: C3.5, F3.2
func num(x interface{}) int { if x==nil{return 0}; switch v:=x.(type) {case float64:return int(v);case int:return v};return 0 }
// derives: C3.5, F3.1
func str(x interface{}) string { if x==nil{return ""}; return fmt.Sprint(x) }
// derives: C3.1, F3.1
func strings(x interface{}) []string { a:=[]string{}; switch v:=x.(type){case []interface{}:for _,i:=range v {a=append(a,str(i))};case []string:a=append(a,v...)}; sort.Strings(a);return a }
// derives: C3.7, C3.8, F3.3
func has(a []string,b string) bool {for _,v:=range a{if v==b{return true}};return false}
// derives: C3.5, F3.2
func input(n string,v interface{},ref M) M {m:=M{"name":n,"value":v};if ref!=nil{m["ref"]=ref};return m}
// derives: C1.3, C2.2, C3.8, F1.1
func ref(r M) M {return M{"proc":r["proc"],"inc":r["inc"],"seq":r["seq"]}}
// derives: C3.5, F1.1, F3.3
func (s *Sim) emit(p,e string,m M,causes ...M) M {n:=s.Nodes[p];n.Seq++;m["proc"]=p;m["inc"]=n.Inc;m["seq"]=n.Seq;m["event"]=e;m["run"]=s.Run;m["side"]="impl";a:=[]M{};for _,c:=range causes {if c!=nil{a=append(a,ref(c))}};m["causes"]=a;s.Trace=append(s.Trace,m);b,_:=json.Marshal(m);fmt.Fprintln(s.Out,string(b));return m}
// derives: F1.1, F1.2, F2.1, F2.2
func (s *Sim) link(a,b string) bool {return a==b || !s.Down[a+">"+b]}
// derives: F1.1, F1.2, F2.1, F2.2
func (s *Sim) send(a,b string,f func()) {if s.Nodes[a].Up && s.link(a,b){s.Queue=append(s.Queue,Task{b,f})}}
// derives: C3.7, C3.8, F3.3
func (s *Sim) eligible(p string) bool {return s.Nodes[p].Inc==0 || s.Nodes[p].Admitted}
// derives: C1.4, C3.4, F2.1, F2.2, F3.3
func (s *Sim) voters(p string,mem []string) []string {a:=[]string{};for _,n:=range mem{if s.Nodes[n].Up && s.eligible(n)&&s.link(p,n)&&s.link(n,p){a=append(a,n)}};return a}
// derives: C3.5, F1.1, F3.1
func (s *Sim) resolve(x string) string {switch x{case "grantor":return s.Grantor;case "holder":return s.Holder;case "non-grantor":for _,n:=range s.S.Processes["lease"]{if n!=s.Grantor&&s.Nodes[n].Up{return n}};case "non-member":for _,n:=range s.S.Processes["lease"]{if !has(s.Members,n){return n}}};return x}
// derives: C3.5, F1.1, F3.1
func (s *Sim) match(t interface{},from int) bool {if str(t)=="start"{return true};m,ok:=t.(map[string]interface{});if !ok{return false};for _,r:=range s.Trace[from:] {yes:=true;for k,v:=range m {if !reflect.DeepEqual(r[k],v)&&str(r[k])!=str(v){yes=false;break}};if yes{return true}};return false}
// derives: C1.1, C3.1, C3.7, C3.8, F1.1, F3.3
// Paxos prepare/accept for one serialized log entry; joint majorities on configuration entries.
